// ../shared/src/provider.ts
function makeProvider(rpcUrl) {
  const url = rpcUrl ?? process.env.BASE_SEPOLIA_RPC_URL ?? process.env.SEPOLIA_RPC_URL;
  if (!url) {
    throw new Error(
      "\u7F3A\u5C11 BASE_SEPOLIA_RPC_URL\uFF1A\u8ACB\u5728 .env \u8A2D\u5B9A Base Sepolia RPC\uFF08\u898B .env.example\uFF09"
    );
  }
  return new ethers_exports.JsonRpcProvider(
    url,
    {
      chainId: AGENT_CHAIN_ID,
      name: AGENT_CHAIN_ID === 84532 ? "base-sepolia" : "sepolia"
    },
    // batchMaxCount: 1 → 關閉 JSON-RPC 請求批次化。ethers v6 預設會把同一個 tick 內
    // 的並發 eth_call（如 getTraderPerformance 的 Promise.all）合併成一個 batch 請求；
    // 公共節點 sepolia.base.org 對 batch 的處理在某些 serverless 區域不穩，會整批卡住
    // （本機正常、Vercel 卡到 30s function timeout）。逐筆送出最穩、相容性最好。
    // staticNetwork → 已給定 chainId，省去網路偵測往返。
    { batchMaxCount: 1, staticNetwork: true }
  );
}
function makeContracts(provider2) {
  return {
    perp: new ethers_exports.Contract(
      ADDRESSES.PerpetualExchange,
      PERPETUAL_EXCHANGE_ABI,
      provider2
    ),
    oracle: new ethers_exports.Contract(ADDRESSES.MockOracle, MOCK_ORACLE_ABI, provider2),
    registry: new ethers_exports.Contract(
      ADDRESSES.StrategyRegistry,
      STRATEGY_REGISTRY_ABI,
      provider2
    )
  };
}
var ZERO = "0x0000000000000000000000000000000000000000";
function makeSigner(provider2) {
  const pk = process.env.AGENT_PRIVATE_KEY?.trim();
  if (!pk || !pk.startsWith("0x") || pk.length !== 66) return null;
  return new ethers_exports.Wallet(pk, provider2 ?? makeProvider());
}
function getSessionManagerAddress() {
  return process.env.SESSION_MANAGER_ADDRESS?.trim() || ZERO;
}

// ../shared/src/format.ts
function fmtUsdc18(v) {
  return Number(ethers_exports.formatUnits(v, 18));
}
function fmtPrice8(v) {
  return Number(ethers_exports.formatUnits(v, 8));
}
function bpsToPercent(bps) {
  return Number(bps) / 100;
}
function fmtTime(unixSec) {
  const n2 = Number(unixSec);
  return n2 > 0 ? new Date(n2 * 1e3).toISOString() : null;
}
function jsonSafe(obj) {
  return JSON.parse(
    JSON.stringify(obj, (_k, v) => typeof v === "bigint" ? v.toString() : v)
  );
}

// ../shared/src/freshness.ts
function classifyTradeFreshness(a) {
  const ageSec = Math.max(0, a.nowSec - a.updatedAtSec);
  return {
    fresh: ageSec <= a.maxPriceAgeSec,
    ageSec,
    maxPriceAgeSec: a.maxPriceAgeSec
  };
}

