async function getTraderPerformance(c, trader) {
  if (!ethers_exports.isAddress(trader)) {
    throw new Error(`\u4E0D\u662F\u5408\u6CD5\u5730\u5740\uFF1A${trader}`);
  }
  const [profile, isEligible, count] = await Promise.all([
    c.registry.traders(trader),
    c.registry.isEligibleTrader(trader),
    c.registry.getStrategyCount(trader)
  ]);
  const isRegistered = Boolean(profile.isRegistered);
  let strategy = [];
  let strategyVersion = null;
  if (Number(count) > 0) {
    const [allocs, versionId] = await c.registry.getLatestStrategy(
      trader
    );
    strategyVersion = Number(versionId);
    strategy = allocs.map((a) => ({
      asset: symbolOfAssetId(String(a.asset)) ?? String(a.asset),
      weightPercent: Number(a.weight) / 100,
      // weight 是 bps（總和 10000）
      direction: a.isLong ? "long" : "short",
      leverage: Number(a.leverage)
    }));
  }
  const ids = await c.perp.getUserPositions(trader);
  let realized = 0, unrealized = 0, open = 0, closed = 0;
  const details = await Promise.all(
    ids.map((id2) => getPositionDetail(c, id2))
  );
  for (const d of details) {
    if (d.isOpen) {
      open++;
      unrealized += d.unrealizedPnL;
    } else {
      closed++;
      realized += d.realizedPnL;
    }
  }
  const suggestion = [];
  for (const leg of strategy) {
    let fundingPct = 0;
    let headwind = false;
    try {
      const fr = await getFundingRate(c, leg.asset);
      fundingPct = fr.fundingRatePercent;
      headwind = fr.direction === "longs_pay" && leg.direction === "long" || fr.direction === "shorts_pay" && leg.direction === "short";
    } catch {
    }
    suggestion.push({
      asset: leg.asset,
      direction: leg.direction,
      leverage: leg.leverage,
      weightPercent: leg.weightPercent,
      fundingRatePercent: fundingPct,
      fundingHeadwind: headwind,
      note: headwind ? `\u505A${leg.direction === "long" ? "\u591A" : "\u7A7A"}\u9700\u4ED8 funding\uFF08${fundingPct}%/interval\uFF09\uFF0C\u9006\u98A8` : `funding \u9806\u98A8\u6216\u4E2D\u6027\uFF08${fundingPct}%/interval\uFF09`
    });
  }
  return {
    trader,
    isRegistered,
    displayName: String(profile.displayName ?? ""),
    registeredAt: fmtTime(profile.createdAt),
    isEligible: Boolean(isEligible),
    strategyVersion,
    strategy,
    positions: {
      total: details.length,
      open,
      closed,
      realizedPnL: realized,
      unrealizedPnL: unrealized,
      netPnL: realized + unrealized
    },
    suggestion
  };
}

