function agentDid(address, chainId = AGENT_CHAIN_ID) {
  return `did:pkh:eip155:${chainId}:${ethers_exports.getAddress(address)}`;
}
function parseDidPkh(did) {
  const m = /^did:pkh:eip155:(\d+):(0x[0-9a-fA-F]{40})$/.exec(did.trim());
  if (!m) throw new Error(`malformed did:pkh: ${did}`);
  return { chainId: Number(m[1]), address: ethers_exports.getAddress(m[2]) };
}

