    type: "ETV",
    name: "Ethereum Token Verification",
    applicable: live.length > 0,
    passed: score <= 20,
    score,
    details: live.length === 0 ? "no on-chain contracts supplied" : missing === 0 ? `all ${live.length} associated contracts present on-chain` : `${missing}/${live.length} associated contracts have no code on-chain`,
    evidence
