  const ttlSec = params.ttlSec ?? Number(process.env.AGENT_ATTESTATION_TTL ?? DEFAULT_ATTESTATION_TTL_SEC);
  const expiresAtSec = issuedAtSec + (Number.isFinite(ttlSec) && ttlSec > 0 ? ttlSec : DEFAULT_ATTESTATION_TTL_SEC);
